<?php
namespace App\Livewire\Admin\Users;use App\Models\User;use Livewire\Attributes\Url;use Livewire\Component;use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $search='';#[Url]public string $role='';public function mount():void{$u=auth()->user();abort_unless($u->isAdmin()||$u->isHR()||$u->hasPermission('users.view'),403);}public function render(){$q=User::query()->withCount(['permissions','permissionGroups'])->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('name','like','%'.$this->search.'%')->orWhere('email','like','%'.$this->search.'%')))->when($this->role,fn($q)=>$q->where('role',$this->role));return view('livewire.admin.users.index',['users'=>$q->orderBy('name')->paginate(30),'roles'=>self::roles()])->layout('components.layouts.admin',['title'=>'Users']);}public static function roles():array{return ['admin'=>'Admin','hr'=>'HR','marketing'=>'Marketing','sales'=>'Sales','operation'=>'Operations','account'=>'Accounts','call_center'=>'Call Centre'];}}
